1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage} from '../../types/messages.js';
6	import type {SessionStore, SessionListOptions} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendStreamEnd,
29	  sendSessionList,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  return function handleMessage(
46	    ws: WebSocket,
47	    session: ChatSession,
48	    rawMessage: unknown,
49	    signal?: AbortSignal
50	  ): Promise<void> {
51	    const validation = validateMessage(rawMessage);
52	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
53	    if (isUserMessageFrame(rawMessage)) {
54	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
55	    }
56	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
57	    return wsErrorHandler(ws, async () => answerFrame(ws, session, sessionStore, validation));
58	  };
59	}
60	
61	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
62	async function answerInTurn(
63	  ws: WebSocket,
64	  session: ChatSession,
65	  orchestrator: ChatOrchestrator,
66	  validation: ValidationResult,
67	  signal: AbortSignal | undefined
68	): Promise<void> {
69	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
70	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
71	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
72	    return;
73	  }
74	  const startedAt = Date.now();
75	  try {
76	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
77	  } finally {
78	    endTurn(ws, session, signal, startedAt);
79	  }
80	}
81	
82	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
83	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
84	  if (signal?.aborted) {
85	    log.info('message', 'turn abandoned: its socket closed', {
86	      sessionId: session.sessionId,
87	      elapsedMs: Date.now() - startedAt,
88	    });
89	    return;
90	  }
91	  sendStreamEnd(ws);
92	}
93	
94	async function answerUserMessage(
95	  ws: WebSocket,
96	  session: ChatSession,
97	  orchestrator: ChatOrchestrator,
98	  validation: ValidationResult,
99	  signal: AbortSignal | undefined
100	): Promise<void> {
101	  if (!checkValidation(ws, validation)) return;
102	
103	  const message = validation.data;
104	  if (message.type === 'user_message') {
105	    await handleUserMessage(ws, session, orchestrator, message.content, signal);
106	  }
107	}
108	
109	async function answerFrame(
110	  ws: WebSocket,
111	  session: ChatSession,
112	  sessionStore: SessionStore | undefined,
113	  validation: ValidationResult
114	): Promise<void> {
115	  if (!checkValidation(ws, validation)) return;
116	
117	  const message = validation.data;
118	  if (message.type === 'ping') handlePing(ws, message.timestamp);
119	  if (message.type === 'list_sessions')
120	    await handleListSessions(
121	      ws,
122	      session,
123	      sessionStore,
124	      message as {type: 'list_sessions'; limit?: number; before?: {updatedAt: string; sessionId: string}}
125	    );
126	}
127	
128	function checkValidation(ws: WebSocket, validation: ValidationResult): boolean {
129	  if (!validation.valid) {
130	    log.warn('message', 'validation failed', {error: validation.error});
131	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
132	    return false;
133	  }
134	  return true;
135	}
136	
137	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
138	function isUserMessageFrame(rawMessage: unknown): boolean {
139	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
140	}
141	
142	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
143	  try {
144	    await action();
145	  } catch (error) {
146	    const message = error instanceof Error ? error.message : 'Unknown error';
147	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
148	    log.error('message', 'handling error', {error: message, code});
149	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
150	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
151	      return;
152	    }
153	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
154	  }
155	}
156	
157	async function handleUserMessage(
158	  ws: WebSocket,
159	  session: ChatSession,
160	  orchestrator: ChatOrchestrator,
161	  content: string,
162	  signal: AbortSignal | undefined
163	): Promise<void> {
164	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
165	
166	  const userEntry = createUserEntry(content);
167	  const userIndex = appendEntry(session, userEntry);
168	  sendUpsert(ws, userIndex, userEntry);
169	
170	  const parser = new ThinkingTagParser();
171	  const state: StreamState = {
172	    thinkingIndex: null,
173	    assistantIndex: null,
174	    suppressOutput: false,
175	    sentAssistantIndices: [],
176	  };
177	
178	  let textChunkCount = 0;
179	
180	  try {
181	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
182	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
183	      if (signal?.aborted) break;
184	      textChunkCount = logChunk(chunk, textChunkCount);
185	      processChunk(ws, session, state, parser, chunk);
186	    }
187	  } finally {
188	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
189	    flushHeldText(ws, session, state, parser);
190	    closeCutOff(ws, session, state, 'thinkingIndex');
191	    closeCutOff(ws, session, state, 'assistantIndex');
192	  }
193	
194	  if (textChunkCount > 0) {
195	    log.debug('stream', `received ${textChunkCount} text chunks`);
196	  }
197	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
198	}
199	
200	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
201	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
202	  if (chunk.type === 'text') return textChunkCount + 1;
203	
204	  if (textChunkCount > 0) {
205	    log.debug('stream', `received ${textChunkCount} text chunks`);
206	  }
207	
208	  if (chunk.type === 'tool_result') {
209	    log.debug('stream', 'tool_result chunk', {
210	      messageCount: chunk.clientMessages.length,
211	      types: chunk.clientMessages.map(m => m.type),
212	    });
213	    return 0;
214	  }
215	
216	  log.debug('stream', 'chunk', {type: chunk.type});
217	  return 0;
218	}
219	
220	function processChunk(
221	  ws: WebSocket,
222	  session: ChatSession,
223	  state: StreamState,
224	  parser: ThinkingTagParser,
225	  chunk: MessageChunk
226	): void {
227	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
228	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
229	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
230	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
231	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
232	}
233	
234	function processTextChunk(
235	  ws: WebSocket,
236	  session: ChatSession,
237	  state: StreamState,
238	  parser: ThinkingTagParser,
239	  text: string
240	): void {
241	  const segments = parser.push(text);
242	  for (const segment of segments) {
243	    handleTextSegment(ws, session, state, segment);
244	  }
245	}
246	
247	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
248	  if (segment.type === 'thinking') {
249	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
250	    return;
251	  }
252	  commitAndClear(ws, session, state, 'thinkingIndex');
253	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
254	}
255	
256	function streamSegment(
257	  ws: WebSocket,
258	  session: ChatSession,
259	  state: StreamState,
260	  key: StateIndexKey,
261	  createEntry: EntryFactory,
262	  content: string
263	): void {
264	  const isNew = initSegment(session, state, key, createEntry);
265	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
266	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
267	  appendDelta(session, state[key]!, content);
268	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
269	}
270	
271	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
272	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
273	  markSuppressed(session, index);
274	  sendSkip(ws, index);
275	}
276	
277	function markSuppressed(session: ChatSession, index: number): void {
278	  const entry = session.entries[index];
279	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
280	}
281	
282	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
283	  if (state[key] !== null) return false;
284	  state[key] = appendEntry(session, createEntry());
285	  return true;
286	}
287	
288	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
289	  const index = state[key];
290	  if (index === null) return;
291	
292	  commitEntry(session, index);
293	  state[key] = null;
294	
295	  // Only what the client received can be retracted, and only assistant entries.
296	  if (state.suppressOutput) return;
297	
298	  sendCommit(ws, index);
299	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
300	}
301	
302	function processToolUseChunk(
303	  ws: WebSocket,
304	  session: ChatSession,
305	  toolCall: {name: string; input: Record<string, unknown>}
306	): void {
307	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
308	  const toolIndex = appendEntry(session, toolEntry);
309	  sendUpsert(ws, toolIndex, toolEntry);
310	}
311	
312	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
313	  for (const msg of clientMessages) {
314	    log.debug('stream', 'forwarding client message to frontend', {
315	      type: msg.type,
316	      index: 'index' in msg ? msg.index : undefined,
317	    });
318	    sendJson(ws, msg);
319	  }
320	}
321	
322	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
323	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
324	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
325	  commitOpenEntries(ws, session, state);
326	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
327	
328	  for (const idx of state.sentAssistantIndices) {
329	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
330	    markSuppressed(session, idx);
331	  }
332	
333	  state.sentAssistantIndices = [];
334	  state.suppressOutput = true;
335	}
336	
337	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
338	  flushHeldText(ws, session, state, parser);
339	  commitOpenEntries(ws, session, state);
340	}
341	
342	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
343	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
344	  for (const segment of parser.flush()) {
345	    handleTextSegment(ws, session, state, segment);
346	  }
347	}
348	
349	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
350	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
351	  const index = state[key];
352	  if (index === null) return;
353	  markTruncated(session, index);
354	  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
355	  commitAndClear(ws, session, state, key);
356	}
357	
358	function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
359	  commitAndClear(ws, session, state, 'thinkingIndex');
360	  commitAndClear(ws, session, state, 'assistantIndex');
361	}
362	
363	function handlePing(ws: WebSocket, timestamp: number): void {
364	  ws.send(JSON.stringify({type: 'pong', timestamp}));
365	}
366	
367	async function handleListSessions(
368	  ws: WebSocket,
369	  session: ChatSession,
370	  sessionStore: SessionStore | undefined,
371	  message: {type: 'list_sessions'; limit?: number; before?: {updatedAt: string; sessionId: string}}
372	): Promise<void> {
373	  if (!sessionStore?.listFor) {
374	    log.debug('ws', 'store has no listFor, answering empty list');
375	    sendSessionList(ws, []);
376	    return;
377	  }
378	
379	  const options: SessionListOptions = {limit: message.limit, before: message.before};
380	  try {
381	    const sessions = await sessionStore.listFor(session.userId, options);
382	    sendSessionList(ws, sessions);
383	  } catch (error) {
384	    const message = error instanceof Error ? error.message : 'Unknown error';
385	    log.error('ws', 'listFor failed', {userId: session.userId, error: message, sessionId: session.sessionId});
386	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
387	  }
388	}
